6.query:
timeseries v = avg(system.cpu.utilization), by:{ benchmark.engine, service.name, k8s.cluster.name }, filter: isNotNull(benchmark.engine) and k8s.cluster.name == "observable-otelarrow"
| summarize metric_series = count(), by:{ engine = benchmark.engine }
| sort metric_series desc

12.query:
timeseries mem = avg(dt.kubernetes.container.memory_working_set), by:{k8s.workload.name, k8s.pod.name}, filter: k8s.cluster.name == "observable-otelarrow" and startsWith(k8s.workload.name, "bench-")
| summarize pods_in_window = countDistinctExact(k8s.pod.name), by:{engine = k8s.workload.name}
| sort engine asc
